await build({entryPoints:['out/module.ts'],bundle:true,format:'esm',outfile:'tools/m.mjs',logLevel:'silent'});
const m = await import('./m.mjs');
const A='ABCDEFabcdef0123 -_.xyzXYZ19';let bad=0;
