 if(JSON.stringify(lw(s))!==JSON.stringify(m.tokens(s))){bad++;if(bad<5)console.log('W',s,lw(s),m.tokens(s))}}
for(let i=0;i<20000;i++){let s='';const n=Math.random()*201|0;for(let j=0;j<n;j++)s+=String.fromCharCode(32+Math.random()*95|0);
 if(lt(s,{length:24})!==m.preview(s)){bad++;if(bad<5)console.log('T',s)}}
console.log('bad',bad);
E
